sources.app.tsx:
// The FrameOS scene store, on the frame. Scenes | Layouts, each filed by
// category: a wide window lists the categories down its left side, always on
// the screen, beside the category picked (Featured first), and a narrow one
// shows them as its front, a grid of tiles as the scenes in them are, a
// category opening in a step of its own. A
// category, Featured or a search is a grid that scrolls and fetches more as it
// goes; a scene's page has Preview and Install, and Open, Update or Delete for
// one the frame holds. The header's back button goes up one step: a scene, its
// category, the store's front.
//
// A tile is the same size in any window: the grid is laid out from the room it
// has, so a window dragged bigger shows more of them. Their size follows the
// panel (smaller on a tiny one, larger on a big screen across a room), never
// the window. E-paper turns pages (one refresh each) instead of scrolling.
//
// Pages of the store come with fetch(), off the render, so a tap answers at
// once and the page fills in a moment later; the frame's host does the
// installing (frameos.store() and frameos.storeAction(), docs/scene-store.md:
// its config.json asks for the "store" permission, which storeAction needs).
// Where a render may wait for the network (no host, the browser preview,
// e-paper: one refresh per answer) a page is fetched in the render instead,
// and where there is no host nothing is installed.
//
// Where you are (the tab, the category or search open, the scene open, how far
// each was scrolled) is the private `spot` field, kept on disk: preview a
// scene, come back to the store, and it opens on the same spot, drawn from
// what it showed before any answer comes back. Pages already seen are kept
// with frameos.remember. Only the rows near what shows are built.
//
// The scenes on the frame that have a newer version in the store are the
// frame's control plane's to say (frameos.store().updates): an Updates entry
// at the top of the categories lists them, each with Update, and Update all
// takes every one the frame may in one push. A frame with no plane lists none.
//
// A layout (a scene that goes around the others, on the Layouts side) is tried
// rather than previewed: the frame takes it beside its scenes as a preview,
// and every scene wears it at once, this store included, until it is kept or
// discarded (docs/scene-store.md "Trying a layout").
//
// It looks like the desktop it runs on: elements name their role in the
// desktop's theme (look="button", docs/jsx-ui.md "Themes"), and keep their own
// look with none.

const DEFAULT_STORE = 'https://cloud.frameos.net'
const FRESH_MS = 5 * 60 * 1000
const RETRY_MS = 30 * 1000
// A page of the store while it scrolls: the most it gives at once, the same at
// every window size, so a window dragged bigger asks for nothing again. On
// e-paper a page is the grid on the screen.
const CHUNK = 24
// Sizes in layout pixels, before the panel's zoom: a tile at its narrowest,
// its height, its icon, the gaps, a section's heading, the header.
const TILE = 96
const PICTURE = 120
const ICON = 52
const GAP = 8
const PAD = 12
const HEAD = 36
const BAR = 52
// The categories' side panel of a wide window, and its rows.
const SIDE = 200
const SIDE_ROW = 34

let zoom = 1
const px = (n) => `${Math.round(n * zoom)}px`

// memo() (docs/jsx-ui.md "Repainting what changed"): a tile called again with
// the same values is the element it made then, which the frame takes back
// without reading. A runtime without it (before 2026.11.14) calls it anew.
const remembered = typeof memo === 'function' ? memo : (component) => component

// While this interpreter lives: what it is waiting for, and what it holds.
const asking = new Set() // the listings being fetched
const failures = new Map() // listing -> { at, code }
const pages = new Map() // listing -> page, as frameos.remember keeps them
let query = null // the search field's text while it is edited
let searchOpen = false
let confirmDelete = ''
let scrolls = null // { front, list, side }: where the scroll boxes are
// What the grid's last get() built: its rows `from` to `to` of `rows`, and the
// pages it holds. A scroll that stays inside them asks for no get() (its
// onScroll returns false): the frame scrolls the tree it has.
let built = null
// Opens a scene's page: the tiles' tap, kept across renders as they are.
let openScene = () => {}

const WORDS = {
  offline: 'The frame is offline.',
  store_unavailable: 'The store did not answer. Try again in a moment.',
  plane_unavailable: 'The control plane did not answer. Try again in a moment.',
  plane_update_required: 'Installing from the frame needs a newer version of its control plane.',
  preview_only: 'This is a preview. Install it from the scene store on your own frame, or at scenes.frameos.net.',
  rate_limited: 'Too many requests. Wait a minute and try again.',
  too_many_scenes: 'This frame holds as many scenes as it can. Delete one first.',
  panel_locked: 'Changes from the frame are turned off by its owner.',
  frame_update_required: 'This scene needs a newer FrameOS on the frame.',
  frame_not_active: 'The frame is not active on its control plane.',
  scene_requires_compilation: 'This scene cannot be installed from the frame.',
  scene_not_allowed: 'This scene cannot be installed from the frame.',
  invalid_scene: 'The store no longer offers this scene.',
  scene_not_assigned: 'This scene is not on the frame any more.',
  already_assigned: 'This scene is on the frame already.',
  last_scene: 'A frame keeps at least one scene.',
  no_room: 'Not enough memory on the frame for that.',
  scenes_payload_too_large: 'This scene is too large for the frame.',
  needs_owner: 'This asks for more access than a frame gives by itself. Install or update it from the control plane.',
}
const BUSY = {
  layout: 'Putting it on',
  install: 'Installing',
  preview: 'Opening the preview',
  update: 'Updating',
  updateAll: 'Updating the scenes',
  remove: 'Deleting',
  discard: 'Discarding the preview',
}

// A tile's color by its category (the dark look; e-paper draws them in ink).
const HUES = {
  photos: '#d97706', art: '#db2777', clocks: '#4f46e5', calendar: '#dc2626', weather: '#0284c7',
  dashboards: '#059669', games: '#7c3aed', fun: '#ea580c', utilities: '#475569', ai: '#c026d3',
  demos: '#0d9488', desktops: '#2563eb', layouts: '#0891b2', devices: '#65a30d', featured: '#3b82f6',
  updates: '#16a34a',
}

// A category's icon on the store's front, drawn as lines in a 24 box; one the
// store adds later gets its first letter.
const SHELF_ICONS = {
  updates: 'M12 19V6M6 11L12 5L18 11',
  featured: 'M12 3l2.7 5.6 6.1.8-4.5 4.2 1.1 6.1L12 16.8l-5.4 2.9 1.1-6.1-4.5-4.2 6.1-.8Z',
  photos: 'M3 5h18v14H3ZM3 16l5-5 4 4 3-3 6 6M15.5 8.5h.01',
  art: 'M4 3h16v18H4ZM8 7h8v10H8Z',
  clocks: 'M12 3a9 9 0 1 0 0 18a9 9 0 1 0 0-18ZM12 7v5l3 2',
  calendar: 'M4 6h16v14H4ZM4 10h16M8 3v5M16 3v5',
  weather: 'M7 18h10a4 4 0 0 0 .4-8A6 6 0 0 0 6 10.5A3.75 3.75 0 0 0 7 18Z',
  dashboards: 'M3 11l9-7 9 7M5 9.5V20h14V9.5M10 20v-5h4v5',
  games: 'M7 8h10a4 4 0 0 1 4 4v1a4 4 0 0 1-7 2.5h-4A4 4 0 0 1 3 13v-1a4 4 0 0 1 4-4ZM8 10.5v4M6 12.5h4M16 11.5h.01M18 13.5h.01',
  fun: 'M12 3a9 9 0 1 0 0 18a9 9 0 1 0 0-18ZM8.5 14.5a4.5 4.5 0 0 0 7 0M9 9.5v.5M15 9.5v.5',
  utilities: 'M15 4l5 5L9 20H4v-5ZM12.5 6.5l5 5',
  ai: 'M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8ZM19 16v4M17 18h4',
  demos: 'M9 3h6M10 3v6l-5 9a2 2 0 0 0 1.7 3h10.6a2 2 0 0 0 1.7-3l-5-9V3M7.5 15h9',
  desktops: 'M3 4h8v7H3ZM13 4h8v7h-8ZM3 13h8v7H3ZM13 13h8v7h-8Z',
  layouts: 'M3 4h18v16H3ZM3 8h18',
  devices: 'M7 2h10v20H7ZM11 18h2',
}

function readSpot(app) {
  let spot = app.state.spot
  if (typeof spot === 'string') {
    try {
      spot = JSON.parse(spot)
    } catch (e) {
      spot = null
    }
  }
  spot = spot && typeof spot === 'object' ? spot : {}
  // Before 2026.11.20 the spot was a shelf and a page of it.
  if ('shelf' in spot) {
    if (spot.shelf && !spot.q) spot.cat = spot.shelf
    if (isLayoutShelf(spot.shelf, spot)) spot.tab = 'layouts'
    delete spot.shelf
  }
  return spot
}

// Written when it changed: a disk field is a write. What was last written is
// kept, so a render that changed nothing reads no state to say so.
let spotText = null
function saveSpot(app, spot) {
  const text = JSON.stringify(spot)
  if (text === spotText) return
  const now = spotText === null ? app.state.spot : undefined
  spotText = text
  if (text !== (typeof now === 'string' ? now : JSON.stringify(now))) frameos.setState('spot', spot)
}

// encodeURIComponent leaves !'()* alone, and the host takes a query string of
// letters, digits and -_.~%&=+, only.
const encode = (text) =>
  encodeURIComponent(text).replace(/[!'()*]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase())

const keyOf = (params) => String(params || '').replace(/&?categories=1/, '')

// The store's layouts' shelves (the listing's categories mark them `layout`;
// these before it did).
const LAYOUT_SHELVES = ['desktops', 'layouts', 'devices']
const isLayoutShelf = (slug, spot) =>
  LAYOUT_SHELVES.includes(slug) || !!((spot && spot.shelves) || []).find((s) => s.slug === slug && s.layout)

// The listing of `cat` ('featured', a shelf) or a search, one page of it.
function paramsFor(view, look, page, limit, needShelves) {
  const parts = []
  if (view.q) parts.push('q=' + encode(view.q))
  else if (view.cat && view.cat !== 'featured') parts.push('category=' + encode(view.cat))
  else {
    // Featured is scenes: the layouts have shelves of their own. A panel
    // that animates gets the scenes made for it first.
    parts.push('exclude=' + LAYOUT_SHELVES.join(','))
    const prefer = [look.round ? 'round' : '', look.fast ? 'fast' : ''].filter(Boolean)
    if (prefer.length) parts.push('prefer=' + prefer.join(','))
  }
  // What this frame cannot run is not offered at all: what needs a fast
  // screen on a slow one (e-paper), a program on a Linux frame or a video on an ESP32.
  const without = [!look.fast ? 'fast' : '', look.embedded ? 'linux' : '', look.embedded ? 'video' : ''].filter(Boolean)
  if (without.length) parts.push('without=' + without.join(','))
  parts.push('page=' + page, 'limit=' + limit)
  if (needShelves) parts.push('categories=1')
  return parts.join('&')
}

// Pages seen: this interpreter's, else frameos.remember's (a key a page, and
// `ages` when each came), the oldest let go past `look.kept`. Before
// 2026.11.20 they were all one value, `pages`, written whole for each page.
function kept(key) {
  if (pages.has(key)) return pages.get(key)
  const page = frameos.recall('p:' + key)
  if (!page || !Array.isArray(page.scenes)) return null
  pages.set(key, page)
  return page
}

function keep(key, answer, look) {
  const page = { at: Date.now(), more: !!answer.more, scenes: answer.scenes.slice(0, CHUNK), categories: answer.categories }
  pages.set(key, page)
  frameos.remember('p:' + key, page)
  const ages = frameos.recall('ages') || {}
  if (!Object.keys(ages).length) frameos.remember('pages', null)
  ages[key] = page.at
  const keys = Object.keys(ages)
  if (keys.length > look.kept) {
    keys.sort((a, b) => ages[a] - ages[b])
    for (const old of keys.slice(0, keys.length - look.kept)) {
      delete ages[old]
      pages.delete(old)
      frameos.remember('p:' + old, null)
    }
  }
  frameos.remember('ages', ages)
}

const listingUrl = (base, params, facts) =>
  `${base}/api/store/device/scenes?${params}${facts && facts.version ? '&version=' + encode(facts.version) : ''}`

const failedRecently = (key) => {
  const failure = failures.get(key)
  return failure && Date.now() - failure.at < RETRY_MS ? failure.code : ''
}

const answered = (answer) => answer && Array.isArray(answer.scenes)

// A page of the store, off the render; the scene draws again when it is in.
function fetchListing(url, key, look) {
  asking.add(key)
  fetch(url, { timeoutMs: 15000 })
    .then((r) => (r.ok ? r.json() : Promise.reject(r.status === 429 ? 'rate_limited' : 'store_unavailable')))
    .then((answer) => {
      if (!answered(answer)) throw 'store_unavailable'
      failures.delete(key)
      keep(key, answer, look)
    })
    .catch((e) => failures.set(key, { at: Date.now(), code: typeof e === 'string' ? e : 'store_unavailable' }))
    .finally(() => {
      asking.delete(key)
      frameos.dispatch('render')
    })
}

// The page for `params`: what is kept, else (when `ask`) asked of the store, in
// the render when `env.sync`. A first page is asked again in the background
// when it is old.
function listing(spot, params, env, ask) {
  const key = keyOf(params)
  let page = kept(key)
  // A first page is asked again when it is old, or when it should have
  // brought the shelves and did not.
  const first = /(^|&)page=1(&|$)/.test(key)
  const old = !page || (first && Date.now() - page.at > FRESH_MS) || (params.includes('categories=1') && !page.categories)
  let error = page ? '' : failedRecently(key)
  if (ask && old && !failedRecently(key) && !asking.has(key)) {
    const url = listingUrl(env.base, params, env.facts)
    if (!env.sync) {
      fetchListing(url, key, env.look)
    } else {
      let code = 'store_unavailable'
      try {
        const response = frameos.httpRequest(url, { timeoutMs: 15000 })
        if (response.status === 429) code = 'rate_limited'
        const answer = response.status === 200 && response.body ? JSON.parse(response.body) : null
        if (answered(answer)) {
          keep(key, answer, env.look)
          page = pages.get(key)
          code = ''
        }
      } catch (e) {
        // the words below
      }
      if (code) {
        failures.set(key, { at: Date.now(), code })
        if (!page) error = code
      }
    }
  }
  if (page && page.categories) spot.shelves = page.categories
  return { page, loading: !page && !error, error }
}

function coverUrl(base, image) {
  return image ? (image.startsWith('/') ? base + image : image) : ''
}

// A store cover is the publisher's picture, often a megabyte of PNG: 6 s a
// card on an ESP32. The store also lists `thumb`, a JPEG of at most
// THUMB_WIDTH on its CDN, which is all a tile needs (and a scene's page on a
// small screen).
const THUMB_WIDTH = 512
const coverFor = (base, scene, width) =>
  coverUrl(base, scene.thumb && width <= THUMB_WIDTH * 1.25 ? scene.thumb : scene.image)

// A picture's width in panel pixels, for `width` layout pixels.
const coverPixels = (look, width) => Math.round(width * zoom * look.scale)

// A theme's color for an SVG: the first `bg-[#…]` (or white, black) among a
// role's classes, a box's or a list of boxes'.
function bgOf(role) {
  const text = Array.isArray(role) ? role.join(' ') : typeof role === 'string' ? role : ''
  const m = /(?:^|\s)bg-(\[#[0-9a-fA-F]{3,8}\]|white|black)(?=\s|$)/.exec(text)
  if (!m) return null
  return m[1] === 'white' ? '#ffffff' : m[1] === 'black' ? '#000000' : m[1].slice(1, -1)
}

// What app.frame says, read once a render: each read of it asks the runtime
// again (a third of a millisecond each on an ESP32, thirty of them a render).
function frameOf(app) {
  const f = app.frame
  return {
    paper: f.paper, color: f.color, fast: f.fast, embedded: f.embedded, theme: f.theme,
    rotate: f.rotate, width: f.width, height: f.height, scale: f.scale, round: f.round,
  }
}

// What the frame is: how it draws, and how much room it has.
function lookOf(frame, context) {
  const paper = frame.paper === true
  const ink = paper || frame.color === false
  // Whether a change shows at once: before 2026.11.10 the runtime said it as `paper`.
  const fast = frame.fast ?? !paper
  const embedded = frame.embedded === true
  const theme = frame.theme && typeof frame.theme === 'object' ? frame.theme : null
  // The room it draws in: a window's or a panel's in a layout, else the panel's,
  // turned (app.frame's size is the panel's before the frame's rotation).
  const turned = (frame.rotate || 0) % 180 !== 0
  const panelWidth = (turned ? frame.height : frame.width) || 0
  const panelHeight = (turned ? frame.width : frame.height) || 0
  const room = roundRoom(frame, context)
  const width = room ? room.side : (context && context.imageWidth) || panelWidth
  const height = room ? room.side : (context && context.imageHeight) || panelHeight
  // How big things are follows the panel, never the window: smaller on a tiny
  // panel, larger on a big screen seen across a room, and in a window of a
  // desktop (smaller than the panel) the desktop's own size.
  const panelShort = Math.min(panelWidth || width, panelHeight || height)
  zoom = Math.max(0.75, Math.min(1.5, Math.round(Math.sqrt(panelShort / 480) * 4) / 4))
  if (!room && (width < panelWidth - 2 || height < panelHeight - 2)) zoom = Math.min(zoom, 1)
  return {
    ink,
    fast,
    // The panel is round (only the circle inside it shows): the scenes made
    // for one first.
    round: frame.round === true,
    embedded,
    width,
    height,
    wide: width / zoom >= 600,
    scale: frame.scale || 1,
    // Pages kept with frameos.remember: an ESP32 holds its JavaScript in
    // PSRAM beside the scene.
    kept: embedded ? 8 : 32,
    bg: ink ? 'bg-white' : 'bg-[#0b0e14]',
    text: ink ? 'text-black' : 'text-white',
    muted: ink ? 'text-black' : 'text-[#8b93a7]',
    line: ink ? 'border-black' : 'border-[#232a3a]',
    accent: ink ? 'bg-black text-white' : 'bg-[#3b82f6] text-white',
    accentText: ink ? 'text-black underline' : 'text-[#60a5fa]',
    soft: ink ? 'bg-white border-2 border-black text-black' : 'bg-[#232a3a] text-white',
    field: ink ? 'bg-white text-black border-2 border-black' : 'bg-[#1a2030] text-white placeholder:text-[#8b93a7]',
    press: !fast ? '' : ink ? 'active:bg-black active:text-white' : 'active:bg-[#1f2738]',
    placeholder: ink ? 'bg-white border-2 border-black' : 'bg-[#1a2030]',
    side: ink ? 'border-r-2 border-black' : 'bg-[#0f131b]',
    // A picture's corners are painted in the color around it: none where a
    // theme's page has no plain color.
    pageColor: bgOf(theme && theme.page) || (theme ? null : ink ? '#ffffff' : '#0b0e14'),
  }
}

const hueOf = (look, slug) =>
  look.ink ? 'bg-white border-2 border-black text-black' : `bg-[${HUES[slug] || '#334155'}] text-white`

// Rounded corners for a picture: the box clips square, so the corners are
// painted over in the color around it, each its own corner-sized drawing. One
// drawing the picture's size (the box minus a rounded box) cost a mask over
// the whole picture on every repaint: half a second a pass on an ESP32.
const corner = (r, color, d, where) => (
  <svg className={`absolute ${where}`} width={r} height={r} viewBox={`0 0 ${r} ${r}`}>
    <path fill={color} d={d} />
  </svg>
)
const Corners = ({ radius, color }) => {
  if (!color) return null
  const r = Math.round(radius * zoom)
  return [
    corner(r, color, `M0 0H${r}A${r} ${r} 0 0 0 0 ${r}Z`, 'top-0 left-0'),
    corner(r, color, `M${r} 0V${r}A${r} ${r} 0 0 0 0 0Z`, 'top-0 right-0'),
    corner(r, color, `M${r} ${r}H0A${r} ${r} 0 0 0 ${r} 0Z`, 'bottom-0 right-0'),
    corner(r, color, `M0 ${r}V0A${r} ${r} 0 0 0 ${r} ${r}Z`, 'bottom-0 left-0'),
  ]
}

// A scene's icon, as the store lists it: one SVG path in a 24 box, filled with
// the text color. Anything else (a store at another address could send it) is
// no icon, and the tile keeps its letter.
const ICON_PATH = /^[Mm][MmLlHhVvCcSsQqTtAaZz0-9eE.,+\- \t\n\r]*$/
const iconOf = (scene) =>
  scene && typeof scene.icon === 'string' && scene.icon.length <= 1024 && ICON_PATH.test(scene.icon) ? scene.icon : ''

const Glyph = ({ size, d, stroke, className = '' }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}] shrink-0 ${className}`}>
    {stroke ? (
      <path fill="none" stroke="currentColor" strokeWidth={stroke} strokeLinecap="round" strokeLinejoin="round" d={d} />
    ) : (
      <path fill="currentColor" d={d} />
    )}
  </svg>
)
const BAG = 'M6 7V6a6 6 0 0 1 12 0v1h2.5l-1 15h-15l-1-15ZM8 7h8V6a4 4 0 0 0-8 0Z'
const SEARCH = 'M10.5 17a6.5 6.5 0 1 1 0-13a6.5 6.5 0 0 1 0 13ZM15.5 15.5L21 21'
const LEFT = 'M15 5L8 12L15 19'
const RIGHT = 'M9 5L16 12L9 19'
const CHECK = 'M5 12.5L10 17.5L19 7'
const UP = 'M12 19V6M6 11L12 5L18 11'
const PLAY = 'M8 5v14l11-7Z'

// Whether the frame's control plane says what has updates: not with no plane,
// nor in the browser preview.
const planeLists = (facts) => !!facts && !facts.removeAny && !facts.previewOnly

// The store scenes on the frame with a newer version, as the plane listed
// them ({store, name, from, to, owner}: `owner` when the new version asks for
// more than the frame may give it); null while not known.
function updatesOf(facts) {
  if (!planeLists(facts) || !Array.isArray(facts.updates)) return null
  return facts.updates.filter(
    (row) => row && typeof row.store === 'string' && typeof row.name === 'string' && row.to > row.from
  )
}

// What the frame holds of a store scene: installed (and how old), previewed.
function standing(scene, facts) {
  if (!facts) return {}
  const mine = (facts.installed || []).find((row) => row.store === scene.id)
  const preview = facts.preview && facts.preview.store === scene.id ? facts.preview : null
  return { mine, preview, newer: !!mine && mine.v < scene.version }
}

const letterOf = (name) => (name || '?').trim().charAt(0).toUpperCase()

// A tile's shape for a grid `tile` wide: with pictures (a fast panel), the
// scene's thumbnail at 4:3 over its name; without (e-paper, where every
// picture is a download in the render and dithers to mush that small), its
// icon over its name, as a desktop shows an app.
function shapeOf(look, tile) {
  const pictures = look.fast
  const box = pictures ? PICTURE : Math.min(ICON, tile - 16)
  const boxH = pictures ? (PICTURE * 3) / 4 : box
  return { w: tile, pictures, box, boxH, h: (pictures ? 4 : 8) + boxH + 6 + 30 + 4 }
}

// A scene in the grid: its picture (the cover's thumbnail, decoded at the size
// it is drawn, on its category's color until it is in) with its icon as a
// badge, or its icon on that color where there is no picture or no room for
// pictures, else its first letter;
// its name under it, and a mark at the corner for what the frame holds of it.
function Tile({ look, scene, base, facts, shape }) {
  const { mine, preview, newer } = standing(scene, facts)
  return (
    <TileView
      key={scene.id}
      scene={scene}
      thumb={shape.pictures ? coverFor(base, scene, coverPixels(look, shape.box)) : ''}
      mark={preview ? PLAY : newer ? UP : mine ? CHECK : ''}
      w={shape.w}
      h={shape.h}
      box={shape.box}
      boxH={shape.boxH}
      pictures={shape.pictures}
      hue={hueOf(look, scene.category)}
      press={look.press}
      accent={look.accent}
      pageColor={look.pageColor}
      z={zoom}
    />
  )
}

// The tile itself, from plain values only, so that memo() finds it the same
// render after render (its tap made inside, as memo() wants).
const TileView = remembered(({ scene, thumb, mark, w, h, box, boxH, pictures, hue, press, accent, pageColor }) => {
  const icon = iconOf(scene)
  // Pictures nearly square in the corners, icons as an app's.
  const r = pictures ? 4 : 12
  return (
    <div
      look="option"
      className={`flex flex-col items-center gap-[${px(6)}] w-[${px(w)}] h-[${px(h)}] pt-[${px(pictures ? 4 : 8)}] rounded-[${px(10)}] shrink-0 ${press}`}
      onClick={() => openScene(scene)}
    >
      <div className={`relative w-[${px(box)}] h-[${px(boxH)}] shrink-0`}>
        <div className={`flex items-center justify-center w-[${px(box)}] h-[${px(boxH)}] rounded-[${px(r)}] ${hue}`}>
          {thumb ? null : icon ? (
            <Glyph d={icon} size={Math.round(Math.min(box, boxH) * (pictures ? 0.42 : 0.58))} />
          ) : (
            <span className={`text-[${px(Math.round(Math.min(box, boxH) / 2.2))}] font-bold`}>{letterOf(scene.name)}</span>
          )}
        </div>
        {thumb ? <img className={`absolute left-0 top-0 w-[${px(box)}] h-[${px(boxH)}] object-cover`} src={thumb} /> : null}
        {thumb ? <Corners radius={r} color={pageColor} /> : null}
        {thumb && icon ? (
          <div className={`absolute left-[${px(5)}] bottom-[${px(5)}] flex items-center justify-center w-[${px(24)}] h-[${px(24)}] rounded-[${px(4)}] ${hue}`}>
            <Glyph d={icon} size={15} />
          </div>
        ) : null}
        {mark ? (
          <div className={`absolute -right-1 -top-1 flex items-center justify-center w-[${px(20)}] h-[${px(20)}] rounded-full ${accent}`}>
            <Glyph d={mark} size={13} stroke={mark === PLAY ? 0 : 3} />
          </div>
        ) : null}
      </div>
      <span className={`w-full px-[${px(4)}] text-[${px(12)}] leading-[${px(15)}] text-center line-clamp-2`}>{scene.name}</span>
    </div>
  )
})

// Whether the grid scrolled to `y` (layout pixels) needs a get(): rows it did
// not build come into sight (rows start PAD_TOP down, `near` built a screen
// past what showed), or it wants a page it does not have (as getInRoom asks
// for them: everything down to a screen and a quarter below what shows).
const PAD_TOP = 4
function gridWants(y) {
  const b = built
  if (!b) return true
  const first = Math.floor(Math.max(0, y - PAD_TOP) / b.rowHeight)
  const last = Math.min(b.rows, Math.ceil((y + b.bodyHeight - PAD_TOP) / b.rowHeight))
  if (first < b.from || last > b.to) return true
  const wantRows = Math.ceil((y + b.bodyHeight * 1.25) / b.rowHeight)
  return b.more && Math.ceil((wantRows * b.cols) / CHUNK) > b.pages
}

const Gap = ({ height }) => (height > 0 ? <div className={`h-[${px(height)}] shrink-0`} /> : null)

// `items` in rows of `cols` tiles; a missing one (still loading) a placeholder.
function Rows({ look, items, cols, shape, base, facts, from = 0, to }) {
  const rows = []
  const last = Math.min(to == null ? Math.ceil(items.length / cols) : to, Math.ceil(items.length / cols))
  for (let r = from; r < last; r++) {
    rows.push(
      <div className={`flex gap-[${px(GAP)}] h-[${px(shape.h)}] shrink-0`}>
        {items.slice(r * cols, r * cols + cols).map((scene) =>
          scene ? (
            Tile({ look, scene, base, facts, shape })
          ) : (
            <div className={`flex flex-col items-center w-[${px(shape.w)}] pt-[${px(shape.pictures ? 4 : 8)}] shrink-0`}>
              <div className={`w-[${px(shape.box)}] h-[${px(shape.boxH)}] rounded-[${px(shape.pictures ? 4 : 12)}] ${look.placeholder}`} />
            </div>
          )
        )}
      </div>
    )
  }
  return rows
}

// A category on the store's front: its tile the size of a scene's, its icon
// on its color where a scene has its picture, its name under it; Updates
// with how many there are.
function ShelfTile({ look, shelf, title, shape, count, onOpen }) {
  const d = SHELF_ICONS[shelf.slug]
  const side = Math.min(shape.box, shape.boxH)
  return (
    <div
      look="option"
      className={`flex flex-col items-center gap-[${px(6)}] w-[${px(shape.w)}] h-[${px(shape.h)}] pt-[${px(shape.pictures ? 4 : 8)}] rounded-[${px(10)}] shrink-0 ${look.press}`}
      onClick={onOpen}
    >
      <div className={`relative w-[${px(shape.box)}] h-[${px(shape.boxH)}] shrink-0`}>
        <div className={`flex items-center justify-center w-[${px(shape.box)}] h-[${px(shape.boxH)}] rounded-[${px(shape.pictures ? 4 : 12)}] ${hueOf(look, shelf.slug)}`}>
          {d ? (
            <Glyph d={d} size={Math.round(side * 0.55)} stroke={2} />
          ) : (
            <span className={`text-[${px(Math.round(side / 2.2))}] font-bold`}>{letterOf(title)}</span>
          )}
        </div>
        {count ? (
          <div className={`absolute -right-1 -top-1 flex items-center justify-center min-w-[${px(22)}] h-[${px(22)}] px-[${px(6)}] rounded-full text-[${px(12)}] font-bold ${look.accent}`}>
            {String(count)}
          </div>
        ) : null}
      </div>
      <span className={`w-full px-[${px(4)}] text-[${px(12)}] leading-[${px(15)}] text-center line-clamp-2`}>{title}</span>
    </div>
  )
}

function Button({ look, strong, onClick, children, disabled }) {
  const tone = disabled ? `${look.soft} opacity-50` : strong ? look.accent : look.soft
  return (
    <div
      look={strong && !disabled ? 'primary' : 'button'}
      className={`flex items-center justify-center gap-[${px(6)}] h-[${px(44)}] px-[${px(18)}] rounded-[${px(10)}] text-[${px(15)}] font-bold ${tone} ${disabled ? '' : look.press}`}
      onClick={disabled ? undefined : onClick}
    >
      {children}
    </div>
  )
}

function shelfTitle(spot, slug) {
  if (slug === 'featured') return 'Featured'
  if (slug === 'updates') return 'Updates'
  const shelf = (spot.shelves || []).find((s) => s.slug === slug)
  return shelf ? shelf.title : slug || ''
}

// What is open below the store's front: a search, a category, or nothing.
const listTitle = (spot) => (spot.q ? `Results for "${spot.q}"` : spot.cat ? shelfTitle(spot, spot.cat) : '')

// The categories, in the side panel or on a narrow front: on Scenes Featured
// and the scenes' shelves, on Layouts the layouts' (their slugs until the
// store said their titles).
function shelvesOf(spot) {
  const all = spot.shelves || []
  if (spot.tab === 'layouts') {
    const layouts = all.filter((s) => isLayoutShelf(s.slug, spot))
    return layouts.length ? layouts : LAYOUT_SHELVES.map((slug) => ({ slug, title: slug }))
  }
  return [{ slug: 'featured', title: 'Featured' }, ...all.filter((s) => !isLayoutShelf(s.slug, spot))]
}

// What the host says of the action this store asked for `scene` (any scene
// while it runs): the words for it, or "".
function statusLine(facts, spot, scene) {
  if (!facts) return ''
  if (facts.busy) return `${BUSY[facts.busy] || 'Working'}…`
  if (!scene || !spot.asked || spot.asked.store !== scene.id) return ''
  if (facts.error) return WORDS[facts.error] || `That did not work (${facts.error}).`
  if (facts.done === 'uptodate') return 'It is the newest version already.'
  if (facts.done === 'install') return 'Installed. It is in the scene list now.'
  if (facts.done === 'update') return 'Updated to the newest version.'
  if (facts.done === 'remove') return 'Deleted from the frame.'
  if (facts.done === 'discard') return 'The preview is gone.'
  return ''
}

// What the host says of an update asked on the Updates page.
function updatesLine(facts, spot) {
  if (!facts) return ''
  if (facts.busy) return `${BUSY[facts.busy] || 'Working'}…`
  if (!spot.asked || spot.asked.from !== 'updates') return ''
  if (facts.error) return WORDS[facts.error] || `That did not work (${facts.error}).`
  if (facts.done === 'uptodate') return 'It is the newest version already.'
  if (facts.done === 'update' || facts.done === 'updateAll') return 'Updated. The new versions reach the frame in a moment.'
  return ''
}

// The Updates page: each store scene on the frame with a newer version, with
// Update, and Update all where more than one may be updated here.
function Updates({ look, spot, facts, rows, save }) {
  const busy = !!(facts && facts.busy)
  const ask = (action, row) => {
    spot.asked = { action, store: row ? row.store : '', from: 'updates' }
    save()
    frameos.storeAction(action, row ? { store: row.store, name: row.name } : {})
  }
  if (!rows) {
    return <div className={`flex items-center justify-center flex-1 text-[${px(15)}] ${look.muted}`}>Looking for updates…</div>
  }
  const movable = rows.filter((row) => !row.owner)
  const count = rows.length === 1 ? 'One scene on this frame has' : `${rows.length} scenes on this frame have`
  return (
    <div className={`flex flex-col gap-[${px(GAP)}] px-[${px(PAD)}] pt-[${px(4)}] pb-[${px(PAD)}]`}>
      <div className={`flex flex-wrap items-center gap-[${px(10)}] shrink-0`}>
        <span className={`flex-1 min-w-0 text-[${px(15)}] ${look.muted}`}>
          {rows.length ? `${count} a newer version.` : 'Every scene from the store is up to date.'}
        </span>
        {movable.length > 1 ? (
          <Button look={look} strong disabled={busy} onClick={() => ask('updateAll')}>Update all</Button>
        ) : null}
      </div>
      {rows.map((row) => (
        <div
          look="card"
          className={`flex items-center gap-[${px(10)}] min-h-[${px(58)}] px-[${px(12)}] py-[${px(6)}] rounded-[${px(10)}] shrink-0 ${look.placeholder}`}
        >
          <div className={`flex flex-col flex-1 min-w-0 gap-[${px(2)}]`}>
            <span className={`text-[${px(15)}] font-bold truncate`}>{row.name}</span>
            <span look="muted" className={`text-[${px(13)}] ${look.muted}`}>
              {row.owner
                ? `Version ${row.to} asks for more access. Update it from the control plane.`
                : `Version ${row.from} to ${row.to}`}
            </span>
          </div>
          {row.owner ? null : (
            <Button look={look} strong={movable.length === 1} disabled={busy} onClick={() => ask('update', row)}>Update</Button>
          )}
        </div>
      ))}
    </div>
  )
}

// Words for a layout's page, whatever the host says of it.
function layoutLine(facts, spot, scene, mine, preview) {
  if (preview) return 'Every scene is wearing it now. Keep it, or discard it to go back.'
  if (mine && facts && facts.layout === mine.id) return 'Every scene on the frame wears it.'
  if (mine) return 'It is on the frame. Use it to put it around every scene.'
  return 'A layout goes around the scenes. Try it to see it on this frame, around this store too.'
}

// The scene page's picture, in layout pixels. Decoded at exactly the size it
// is drawn, so drawing it is a copy: one decoded at the panel's width and
// drawn 40 px narrower was resampled on every repaint (0.44 s on an ESP32).
function bigCoverWidth(look, room) {
  return look.wide
    ? Math.min(Math.round(((look.width / zoom) * 0.46) / 4) * 4, Math.round(((room - 56) * 4) / 3))
    : Math.min(Math.round(look.width / zoom - 40), Math.round(((room * 0.45) * 4) / 3))
}

function Detail({ look, spot, facts, base, hasHost, room, save }) {
  const scene = spot.detail
  const { mine, preview, newer } = standing(scene, facts)
  // An update only the owner may take (it asks for more access).
  const owners = newer && (updatesOf(facts) || []).some((row) => row.store === scene.id && row.owner)
  const isLayout = isLayoutShelf(scene.category, spot)
  const busy = !!(facts && facts.busy)
  const ask = (action, extra) => {
    spot.asked = { action, store: scene.id }
    save()
    frameos.storeAction(action, { store: scene.id, name: scene.name, ...extra })
  }
  // The layout the frame wore before a try, put back by Discard.
  const tryLayout = () => {
    spot.tried = { store: scene.id, before: (facts && facts.layout) || '' }
    ask('preview', { show: false })
  }
  const useLayout = (id) => {
    spot.tried = null
    save()
    frameos.storeAction('layout', { id })
  }
  const discard = () => {
    const before = spot.tried && spot.tried.store === scene.id ? spot.tried.before : ''
    spot.tried = null
    ask('discard')
    if (isLayout) frameos.storeAction('layout', { id: before })
  }
  const big = bigCoverWidth(look, room)
  const bigHeight = Math.round((big * 3) / 4)
  // The larger copy (the thumbnail again where that is big enough).
  const bigUrl = coverFor(base, scene, coverPixels(look, big))
  // The browser preview's host previews, and installs nothing.
  const previewOnly = !!(facts && facts.previewOnly)
  const buttons = []
  if (!hasHost) {
    buttons.push(<span className={`text-[${px(14)}] ${look.muted}`}>Previews and installs happen on the frame itself.</span>)
  } else if (preview && isLayout) {
    // Kept: installed and put around every scene by the plane, so the
    // frame's own choice goes back to each scene's (now this one).
    if (!previewOnly) {
      buttons.push(
        <Button look={look} strong disabled={busy} onClick={() => { spot.tried = null; ask('install', { show: true }); frameos.storeAction('layout', { id: '' }) }}>Keep</Button>
      )
    }
    buttons.push(<Button look={look} strong={previewOnly} disabled={busy} onClick={discard}>Discard</Button>)
  } else if (preview) {
    if (!previewOnly) {
      buttons.push(<Button look={look} strong disabled={busy} onClick={() => ask('install', { show: true })}>Install</Button>)
    }
    buttons.push(
      <Button look={look} strong={previewOnly} disabled={busy} onClick={() => frameos.dispatch('setCurrentScene', { sceneId: preview.id })}>Show</Button>,
      <Button look={look} disabled={busy} onClick={discard}>Discard</Button>
    )
  } else if (previewOnly) {
    buttons.push(
      isLayout ? (
        <Button look={look} strong disabled={busy} onClick={tryLayout}>Try</Button>
      ) : (
        <Button look={look} strong disabled={busy} onClick={() => ask('preview')}>Preview</Button>
      )
    )
    buttons.push(<span className={`text-[${px(14)}] ${look.muted}`}>This is a preview. Install it from the scene store on your own frame, or at scenes.frameos.net.</span>)
  } else if (mine) {
    if (!isLayout) {
      buttons.push(
        <Button look={look} strong={!newer} disabled={busy} onClick={() => frameos.dispatch('setCurrentScene', { sceneId: mine.id })}>Open</Button>
      )
    } else if (facts.layout !== mine.id) {
      buttons.push(<Button look={look} strong={!newer} disabled={busy} onClick={() => useLayout(mine.id)}>Use</Button>)
    }
    if (newer && !owners) buttons.push(<Button look={look} strong disabled={busy} onClick={() => ask('update')}>Update</Button>)
    buttons.push(
      confirmDelete === scene.id ? (
        <Button look={look} disabled={busy} onClick={() => { confirmDelete = ''; ask('remove') }}>Tap again to delete</Button>
      ) : (
        <Button look={look} disabled={busy} onClick={() => { confirmDelete = scene.id }}>Delete</Button>
      )
    )
  } else if (isLayout) {
    buttons.push(<Button look={look} strong disabled={busy} onClick={tryLayout}>Try</Button>)
    buttons.push(<Button look={look} disabled={busy} onClick={() => ask('install', { show: false })}>Install</Button>)
  } else {
    buttons.push(<Button look={look} disabled={busy} onClick={() => ask('preview')}>Preview</Button>)
    buttons.push(<Button look={look} strong disabled={busy} onClick={() => ask('install', { show: false })}>Install</Button>)
  }
  const status = statusLine(facts, spot, scene)
  const icon = iconOf(scene)
  const title = <span className={`text-[${px(26)}] font-bold leading-tight line-clamp-2`}>{scene.name}</span>
  const info = (
    <div className={`flex flex-col gap-[${px(10)}] flex-1 min-w-0 self-stretch justify-center`}>
      {icon ? (
        <div className={`flex items-center gap-[${px(10)}] min-w-0`}>
          <div className={`flex items-center justify-center w-[${px(40)}] h-[${px(40)}] rounded-[${px(10)}] shrink-0 ${hueOf(look, scene.category)}`}>
            <Glyph d={icon} size={24} />
          </div>
          {title}
        </div>
      ) : (
        title
      )}
      <span look="muted" className={`text-[${px(14)}] ${look.muted} truncate`}>
        {[scene.by || 'FrameOS', shelfTitle(spot, scene.category), `version ${scene.version}`].filter(Boolean).join(' · ')}
      </span>
      {scene.about ? <span className={`text-[${px(15)}] leading-snug line-clamp-5`}>{scene.about}</span> : null}
      {isLayout ? <span look="muted" className={`text-[${px(13)}] ${look.muted}`}>{layoutLine(facts, spot, scene, mine, preview)}</span> : null}
      {mine && newer ? (
        <span look="muted" className={`text-[${px(13)}] ${look.muted}`}>
          {owners
            ? `The frame has version ${mine.v}. The new one asks for more access: update it from the control plane.`
            : `The frame has version ${mine.v}.`}
        </span>
      ) : null}
      <div className={`flex flex-wrap items-center gap-[${px(8)}] pt-[${px(4)}]`}>{buttons}</div>
      {status ? <span className={`text-[${px(14)}] ${look.accentText}`}>{status}</span> : null}
    </div>
  )
  const picture = (
    <div className={`relative w-[${px(big)}] h-[${px(bigHeight)}] shrink-0`}>
      <div className={`flex items-center justify-center w-[${px(big)}] h-[${px(bigHeight)}] rounded-[${px(6)}] ${hueOf(look, scene.category)}`}>
        {icon ? <Glyph d={icon} size={Math.round(bigHeight / 2.4)} /> : <span className={`text-[${px(Math.round(bigHeight / 2.6))}] font-bold`}>{letterOf(scene.name)}</span>}
      </div>
      {bigUrl ? <img className={`absolute left-0 top-0 w-[${px(big)}] h-[${px(bigHeight)}] object-cover`} src={bigUrl} /> : null}
      {bigUrl ? <Corners radius={6} color={look.pageColor} /> : null}
    </div>
  )
  return look.wide ? (
    <div className={`flex flex-1 min-h-0 items-center gap-[${px(22)}] px-[${px(20)}] pb-[${px(20)}]`}>
      {picture}
      {info}
    </div>
  ) : (
    <div className={`flex flex-col flex-1 min-h-0 items-center gap-[${px(14)}] px-[${px(20)}] pb-[${px(16)}] overflow-y-auto`} scrollTop={0}>
      {picture}
      {info}
    </div>
  )
}

function getInRoom(app, frame, context) {
  built = null // the grid's, when it draws below
  const look = lookOf(frame, context)
  const facts = frameos.store()
  const hasHost = !!facts
  const base = String((facts && facts.url) || DEFAULT_STORE).replace(/\/+$/, '')
  // Where a render may wait for a page: no host, the browser preview, and a
  // slow panel (e-paper), which draws once per answer (a refresh to say
  // "Loading" costs seconds).
  const sync = !hasHost || !look.fast || !!facts.previewOnly
  const env = { base, facts, look, sync }
  const spot = readSpot(app)
  spot.tab = spot.tab === 'layouts' ? 'layouts' : 'scenes'
  spot.page = Math.max(1, spot.page || 1)
  if (!scrolls) scrolls = { front: 0, list: 0, side: 0, ...(spot.scroll || {}) }
  const save = () => {
    spot.scroll = { front: scrolls.front, list: scrolls.list, side: scrolls.side }
    saveSpot(app, spot)
  }
  // A wide window lists the categories down its left side, always there: it
  // has no front of its own, and opens on its tab's first category.
  const side = look.wide
  // Updates where the plane says what has them (no plane: a spot from before
  // goes back to the categories).
  const updates = updatesOf(facts)
  if (spot.cat === 'updates' && !planeLists(facts)) spot.cat = ''
  if (side && !spot.cat && !spot.q) spot.cat = shelvesOf(spot)[0].slug
  // A layout being tried: once the frame holds it (the preview is in), every
  // scene wears it, this store too; the host shows the store again in it.
  const tried = spot.tried
  if (tried && facts && facts.preview && facts.preview.store === tried.store && facts.preview.id && facts.layout !== facts.preview.id) {
    frameos.storeAction('layout', { id: facts.preview.id })
  }

  const go = (change) => {
    Object.assign(spot, change)
    confirmDelete = ''
    save()
  }
  // Up one step: a scene's page to where it was opened, a category or a search
  // to the store's front.
  const back = () => {
    if (spot.detail) return go({ detail: null })
    query = null
    searchOpen = false
    go({ q: '', cat: '', page: 1 })
  }
  const open = (scene) => go({ detail: scene })
  openScene = open
  const openShelf = (slug) => {
    scrolls.list = 0
    query = null
    searchOpen = false
    // Updates are on both sides: the side open stays.
    const tab = slug === 'updates' ? spot.tab : isLayoutShelf(slug, spot) ? 'layouts' : 'scenes'
    go({ cat: slug, q: '', page: 1, detail: null, tab })
  }
  const search = () => {
    const text = String(query == null ? spot.q || '' : query).trim()
    query = null
    searchOpen = false
    scrolls.list = 0
    go({ q: text, cat: text ? '' : spot.cat, page: 1, detail: null })
  }

  const width = look.width / zoom
  const height = look.height / zoom
  const level = spot.detail ? 2 : spot.q || spot.cat ? 1 : 0
  const listed = level >= 1 ? spot : null
  const status = statusLine(facts, spot, spot.detail)
  // What the header shows as the store's front: the front itself, or, beside
  // the side panel, always (the way back from a scene is the pane's).
  const front = level === 0 || side

  // The header: the way back (saying where it goes), what shows, and search.
  const narrowFront = level === 0 && !look.wide
  const searching = searchOpen || !!spot.q
  const searchField = (
    <div look="field" className={`flex items-center gap-[${px(8)}] h-[${px(38)}] px-[${px(12)}] rounded-[${px(10)}] ${look.field} ${look.wide ? `w-[${px(220)}] shrink-0` : 'flex-1 min-w-0'}`}>
      <Glyph d={SEARCH} size={17} stroke={2.6} />
      <input
        className={`flex-1 min-w-0 h-[${px(38)}] text-[${px(15)}] bg-transparent`}
        value={query == null ? spot.q || '' : query}
        placeholder="Search the store"
        onChange={(e) => {
          query = e.target.value
        }}
        onKeyDown={(e) => {
          if (e.key === 'Enter') search()
        }}
      />
    </div>
  )
  const tabs = (
    <div className={`flex gap-[${px(4)}] ${look.wide ? '' : 'flex-1'}`}>
      {[['scenes', 'Scenes'], ['layouts', 'Layouts']].map(([id, words]) => (
        <div
          look={spot.tab === id ? 'selected' : 'button'}
          className={`flex items-center justify-center h-[${px(34)}] px-[${px(14)}] rounded-[${px(9)}] text-[${px(14)}] font-bold ${look.wide ? '' : 'flex-1'} ${spot.tab === id ? look.accent : `${look.soft} ${look.press}`}`}
          onClick={() => {
            if (spot.tab === id) return
            scrolls.front = 0
            scrolls.list = 0
            scrolls.side = 0
            // Beside the side panel, the tab's first category.
            if (side) go({ tab: id, cat: shelvesOf({ ...spot, tab: id })[0].slug, q: '', page: 1, detail: null })
            else go({ tab: id })
          }}
        >
          {words}
        </div>
      ))}
    </div>
  )
  const backTo = level === 2 ? listTitle(spot) || 'Store' : 'Store'
  const header = (
    <div look="bar" className={`flex flex-col gap-[${px(8)}] px-[${px(PAD)}] pt-[${px(8)}] pb-[${px(6)}] shrink-0`}>
      <div className={`flex items-center gap-[${px(10)}] h-[${px(38)}]`}>
        {front ? (
          <div className={`flex items-center justify-center w-[${px(32)}] h-[${px(32)}] rounded-[${px(9)}] shrink-0 ${look.accent}`}>
            <Glyph d={BAG} size={18} />
          </div>
        ) : (
          <div
            look="button"
            className={`flex items-center gap-[${px(2)}] h-[${px(36)}] pl-[${px(4)}] pr-[${px(10)}] rounded-[${px(9)}] min-w-0 shrink ${look.soft} ${look.press}`}
            onClick={back}
          >
            <Glyph d={LEFT} size={20} stroke={2.8} />
            <span className={`text-[${px(14)}] font-bold truncate`}>{backTo}</span>
          </div>
        )}
        {front ? (
          <span className={`text-[${px(18)}] font-bold whitespace-nowrap`}>Scene store</span>
        ) : level === 1 ? (
          <span className={`flex-1 min-w-0 text-[${px(18)}] font-bold truncate`}>{listTitle(spot)}</span>
        ) : (
          <div className="flex-1" />
        )}
        {front && look.wide ? tabs : null}
        {front ? <div className="flex-1" /> : null}
        {(level < 2 || side) && look.wide ? searchField : null}
        {level < 2 && !look.wide ? (
          <div
            look={searching ? 'selected' : 'button'}
            className={`flex items-center justify-center w-[${px(38)}] h-[${px(38)}] rounded-[${px(10)}] shrink-0 ${searching ? look.accent : look.soft} ${look.press}`}
            onClick={() => { searchOpen = !searchOpen }}
          >
            <Glyph d={SEARCH} size={17} stroke={2.6} />
          </div>
        ) : null}
      </div>
      {level < 2 && !look.wide && searching ? (
        <div className={`flex h-[${px(38)}]`}>{searchField}</div>
      ) : narrowFront ? (
        <div className={`flex h-[${px(34)}]`}>{tabs}</div>
      ) : null}
    </div>
  )
  const headerHeight = 8 + 38 + 6 + ((level < 2 && !look.wide && searching) || narrowFront ? 8 + (searching ? 38 : 34) : 0)

  // The grid: tiles at their size, as many across as the room takes, beside
  // the side panel where there is one, under the category's name.
  const paneWidth = side ? width - SIDE : width
  const paneHead = side && level >= 1 ? HEAD : 0
  const room = paneWidth - PAD * 2
  const least = look.fast ? PICTURE : TILE
  const cols = Math.max(2, Math.floor((room + GAP) / (least + GAP)))
  const shape = shapeOf(look, Math.floor((room - GAP * (cols - 1)) / cols))
  const rowHeight = shape.h + GAP
  const footerHeight = !look.fast && level === 1 ? 46 : status ? 30 : 0
  const bodyHeight = Math.max(rowHeight, height - headerHeight - footerHeight - paneHead)
  const needShelves = !spot.shelves
  // E-paper's page: the grid on its screen.
  const limit = look.fast ? CHUNK : Math.min(CHUNK, cols * Math.max(1, Math.floor((bodyHeight - PAD + GAP) / rowHeight)))

  // Updates first, where there are any: a count of them beside the name.
  const count = (on) => (
    <div className={`flex items-center justify-center min-w-[${px(22)}] h-[${px(22)}] px-[${px(6)}] rounded-full shrink-0 text-[${px(12)}] font-bold ${on ? look.soft : look.accent}`}>
      {String(updates.length)}
    </div>
  )
  const updatesEntry = updates && updates.length > 0
  // The side panel: Updates, Featured and the tab's categories, the one showing lit.
  const sidePanel = side ? (
    <div
      look="card"
      className={`flex flex-col gap-[${px(2)}] w-[${px(SIDE)}] shrink-0 min-h-0 overflow-y-auto px-[${px(8)}] py-[${px(6)}] ${look.side}`}
      scrollTop={Math.round(scrolls.side * zoom)}
      onScroll={(e) => {
        scrolls.side = Math.max(0, Math.round(e.scrollTop / zoom))
      }}
    >
      {updatesEntry ? (
        <div
          look={spot.cat === 'updates' && !spot.q ? 'picked' : 'option'}
          className={`flex items-center gap-[${px(9)}] h-[${px(SIDE_ROW)}] px-[${px(9)}] rounded-[${px(7)}] shrink-0 ${spot.cat === 'updates' && !spot.q ? look.accent : look.press}`}
          onClick={() => openShelf('updates')}
        >
          <Glyph d={UP} size={14} stroke={2.8} />
          <span className={`flex-1 min-w-0 text-[${px(14)}] font-bold truncate`}>Updates</span>
          {count(spot.cat === 'updates' && !spot.q)}
        </div>
      ) : null}
      {shelvesOf(spot).map((shelf) => {
        const on = !spot.q && spot.cat === shelf.slug
        return (
          <div
            look={on ? 'picked' : 'option'}
            className={`flex items-center gap-[${px(9)}] h-[${px(SIDE_ROW)}] px-[${px(9)}] rounded-[${px(7)}] shrink-0 ${on ? look.accent : look.press}`}
            onClick={() => openShelf(shelf.slug)}
          >
            <div className={`w-[${px(10)}] h-[${px(10)}] rounded-full shrink-0 ${look.ink ? 'border-2 border-current' : `bg-[${HUES[shelf.slug] || '#334155'}]`}`} />
            <span className={`flex-1 min-w-0 text-[${px(14)}] truncate ${on ? 'font-bold' : ''}`}>{shelfTitle(spot, shelf.slug) || shelf.title}</span>
          </div>
        )
      })}
    </div>
  ) : null
  const page = (body, footer) =>
    side ? (
      <div look="page" className={`flex flex-col w-full h-full ${look.bg} ${look.text}`}>
        {header}
        <div className="flex flex-1 min-h-0">
          {sidePanel}
          <div className="flex flex-col flex-1 min-w-0 min-h-0">
            {paneHead && level === 2 ? (
              <div className={`flex items-center h-[${px(HEAD)}] px-[${px(PAD)}] shrink-0`}>
                <div
                  look="button"
                  className={`flex items-center gap-[${px(2)}] h-[${px(30)}] pl-[${px(4)}] pr-[${px(10)}] rounded-[${px(8)}] min-w-0 shrink ${look.soft} ${look.press}`}
                  onClick={back}
                >
                  <Glyph d={LEFT} size={18} stroke={2.8} />
                  <span className={`text-[${px(14)}] font-bold truncate`}>{backTo}</span>
                </div>
              </div>
            ) : paneHead ? (
              <div className={`flex items-center h-[${px(HEAD)}] px-[${px(PAD)}] shrink-0`}>
                <span className={`flex-1 min-w-0 text-[${px(17)}] font-bold truncate`}>{listTitle(spot)}</span>
              </div>
            ) : null}
            {body}
            {footer || null}
          </div>
        </div>
      </div>
    ) : (
      <div look="page" className={`flex flex-col w-full h-full ${look.bg} ${look.text}`}>
        {header}
        {body}
        {footer || null}
      </div>
    )
  const statusBar = status ? (
    <div className={`flex items-center h-[${px(30)}] px-[${px(PAD)}] shrink-0`}>
      <span className={`flex-1 min-w-0 text-[${px(13)}] truncate ${look.accentText}`}>{status}</span>
    </div>
  ) : null
  const trouble = (error, again) => (
    <div className={`flex flex-col items-center justify-center flex-1 self-stretch gap-[${px(12)}] px-[${px(PAD)}] ${look.muted}`}>
      <span className={`text-[${px(16)}] text-center`}>{WORDS[error] || 'The store did not answer.'}</span>
      <Button look={look} onClick={again}>Try again</Button>
    </div>
  )
  const retry = (key) => () => {
    failures.delete(key)
    go({})
  }
  // A box that scrolls. Only what is near the screen is built (`near`: a
  // screen above it and below), spacers stand for the rest. Its onScroll asks
  // for a get() only when what shows leaves what was built, or nears the end
  // of the pages there are (`gridWants`): otherwise the frame scrolls the
  // tree it has, and a finger's drag is a layout and a repaint, no JavaScript.
  const scroller = (which, children) => (
    <div
      className={`flex flex-col flex-1 min-h-0 overflow-y-auto`}
      scrollTop={Math.round(scrolls[which] * zoom)}
      onScroll={(e) => {
        scrolls[which] = Math.max(0, Math.round(e.scrollTop / zoom))
        return which === 'list' && gridWants(scrolls.list)
      }}
    >
      {children}
    </div>
  )
  const near = (which) => [scrolls[which] - bodyHeight, scrolls[which] + bodyHeight * 2]

  if (level === 2) {
    saveSpot(app, spot)
    // Beside the side panel, laid out for the pane's width.
    const paneLook = side ? { ...look, width: paneWidth * zoom, wide: paneWidth >= 560 } : look
    return page(<Detail look={paneLook} spot={spot} facts={facts} base={base} hasHost={hasHost} room={bodyHeight} save={save} />)
  }

  if (level === 1 && !spot.q && spot.cat === 'updates') {
    saveSpot(app, spot)
    const line = updatesLine(facts, spot)
    return page(
      scroller('list', <Updates look={look} spot={spot} facts={facts} rows={updates} save={save} />),
      line ? (
        <div className={`flex items-center h-[${px(30)}] px-[${px(PAD)}] shrink-0`}>
          <span className={`flex-1 min-w-0 text-[${px(13)}] truncate ${look.accentText}`}>{line}</span>
        </div>
      ) : null
    )
  }

  if (level === 1 && !look.fast) {
    // E-paper: a page a screen, turned by the arrows or a swipe.
    const params = paramsFor(listed, look, spot.page, limit, needShelves)
    const { page: answer, loading, error } = listing(spot, params, env, true)
    const scenes = answer ? answer.scenes.slice(0, limit) : []
    const more = answer ? answer.more : false
    const turn = (by) => {
      if ((by > 0 && !more) || (by < 0 && spot.page <= 1)) return
      go({ page: spot.page + by })
    }
    saveSpot(app, spot)
    const body =
      error && !scenes.length ? (
        trouble(error, retry(keyOf(params)))
      ) : !loading && !scenes.length ? (
        <div className={`flex items-center justify-center flex-1 text-[${px(16)}] ${look.muted}`}>{spot.q ? 'No scenes match that.' : 'Nothing here yet.'}</div>
      ) : (
        <div
          className={`flex flex-col flex-1 min-h-0 gap-[${px(GAP)}] px-[${px(PAD)}]`}
          onSwipe={(e) => {
            if (e.direction === 'left') turn(1)
            else if (e.direction === 'right') turn(-1)
          }}
        >
          <Rows look={look} items={loading ? Array(cols).fill(null) : scenes} cols={cols} shape={shape} base={base} facts={facts} />
        </div>
      )
    const arrow = (by, on) => (
      <div
        look="button"
        className={`flex items-center justify-center w-[${px(40)}] h-[${px(34)}] rounded-[${px(8)}] ${on ? look.soft : `${look.muted} opacity-40`}`}
        onClick={() => turn(by)}
      >
        <Glyph d={by < 0 ? LEFT : RIGHT} size={18} stroke={2.8} />
      </div>
    )
    return page(
      body,
      <div className={`flex items-center justify-between h-[${px(46)}] px-[${px(PAD)}] shrink-0`}>
        <span className={`flex-1 min-w-0 text-[${px(13)}] truncate ${look.accentText}`}>{status}</span>
        <div className={`flex items-center gap-[${px(6)}]`}>
          {arrow(-1, spot.page > 1)}
          <span className={`w-[${px(64)}] text-center text-[${px(13)}] ${look.muted}`}>{`Page ${spot.page}`}</span>
          {arrow(1, more)}
        </div>
      </div>
    )
  }

  if (level === 1) {
    // A category, Featured or a search: one grid that scrolls, its pages
    // fetched as the end comes near: every page down to a screen below what
    // shows, at once (a spot opened again far down asks for them together).
    const [top, bottom] = near('list')
    const wantRows = Math.ceil((scrolls.list + bodyHeight * 1.25) / rowHeight)
    const wantPages = Math.max(1, Math.ceil((wantRows * cols) / CHUNK))
    const scenes = []
    let more = true
    let waiting = false
    let first = null
    for (let p = 1; more && p <= 40; p++) {
      const params = paramsFor(listed, look, p, CHUNK, needShelves && p === 1)
      const state = listing(spot, params, env, p <= wantPages)
      if (p === 1) first = { error: state.error, key: keyOf(params) }
      if (!state.page) {
        waiting = !state.error
        for (let q = p + 1; q <= wantPages; q++) listing(spot, paramsFor(listed, look, q, CHUNK, false), env, true)
        break
      }
      scenes.push(...state.page.scenes)
      more = state.page.more
    }
    saveSpot(app, spot)
    if (!scenes.length && first.error) return page(trouble(first.error, retry(first.key)), statusBar)
    if (!scenes.length && !waiting) {
      return page(
        <div className={`flex items-center justify-center flex-1 text-[${px(16)}] ${look.muted}`}>{spot.q ? 'No scenes match that.' : 'Nothing here yet.'}</div>,
        statusBar
      )
    }
    // Placeholders for what is still coming: down to what shows, or a row.
    const coming = waiting ? Math.max(wantRows * cols, scenes.length + cols) : more ? scenes.length + cols : scenes.length
    const items = scenes.concat(Array(coming - scenes.length).fill(null))
    const rows = Math.ceil(items.length / cols)
    const from = Math.max(0, Math.floor(top / rowHeight))
    const to = Math.min(rows, Math.ceil(bottom / rowHeight) + 1)
    built = { from, to, rows, rowHeight, bodyHeight, cols, pages: Math.ceil(scenes.length / CHUNK), more }
    return page(
      scroller(
        'list',
        <div className={`flex flex-col gap-[${px(GAP)}] px-[${px(PAD)}] pt-[${px(PAD_TOP)}] pb-[${px(PAD)}]`}>
          <Gap height={from * rowHeight - GAP} />
          <Rows look={look} items={items} cols={cols} shape={shape} base={base} facts={facts} from={from} to={to} />
          <Gap height={(rows - to) * rowHeight - GAP} />
        </div>
      ),
      statusBar
    )
  }

  // The store's front, on a narrow window: its categories as a grid, tiles
  // the size of the scenes' in them, each opened in a step of its own (a wide
  // window lists them down its side). The shelves come with the first page
  // of Featured.
  const featured = paramsFor({ cat: 'featured' }, look, 1, limit, needShelves)
  const first = needShelves ? listing(spot, featured, env, true) : null
  const shelves = shelvesOf(spot)
  saveSpot(app, spot)
  if (first && !spot.shelves) {
    if (first.error) return page(trouble(first.error, retry(keyOf(featured))), statusBar)
    return page(<div className={`flex items-center justify-center flex-1 text-[${px(15)}] ${look.muted}`}>Loading…</div>, statusBar)
  }
  // Updates first, where there are any.
  const tiles = (updatesEntry ? [{ slug: 'updates', title: 'Updates' }] : []).concat(shelves)
  const rowsOf = []
  for (let i = 0; i < tiles.length; i += cols) {
    rowsOf.push(
      <div className={`flex gap-[${px(GAP)}] h-[${px(shape.h)}] shrink-0`}>
        {tiles.slice(i, i + cols).map((shelf) => (
          <ShelfTile
            look={look}
            shelf={shelf}
            title={shelfTitle(spot, shelf.slug) || shelf.title}
            shape={shape}
            count={shelf.slug === 'updates' ? updates.length : 0}
            onOpen={() => openShelf(shelf.slug)}
          />
        ))}
      </div>
    )
  }
  return page(
    scroller('front', <div className={`flex flex-col gap-[${px(GAP)}] px-[${px(PAD)}] pt-[${px(PAD_TOP)}] pb-[${px(PAD)}]`}>{rowsOf}</div>),
    statusBar
  )
}

// A round panel (app.frame.round) shows only the circle inside its square.
// Drawn on the whole panel, the app lays out in the square inside that circle
// and is drawn there; in a window or a layout's hole its room is its own.
function roundRoom(frame, context) {
  if (frame.round !== true) return null
  const turned = (frame.rotate || 0) % 180 !== 0
  const panelWidth = (turned ? frame.height : frame.width) || 0
  const panelHeight = (turned ? frame.width : frame.height) || 0
  if (context && context.imageWidth && (Math.abs(context.imageWidth - panelWidth) > 2 || Math.abs(context.imageHeight - panelHeight) > 2)) {
    return null
  }
  const side = Math.floor((Math.min(panelWidth, panelHeight) / 2 - 12) * Math.SQRT2)
  return {
    width: panelWidth,
    height: panelHeight,
    side,
    x: Math.floor((panelWidth - side) / 2),
    y: Math.floor((panelHeight - side) / 2),
  }
}

export function get(app, context) {
  const frame = frameOf(app)
  const ui = getInRoom(app, frame, context)
  const room = roundRoom(frame, context)
  if (!room || !ui || typeof ui !== 'object') return ui
  return (
    <div className={`relative w-[${room.width}px] h-[${room.height}px]`}>
      <div className={`absolute left-[${room.x}px] top-[${room.y}px] w-[${room.side}px] h-[${room.side}px]`}>{ui}</div>
    </div>
  )
}
